function QrPayment() {
  const history = useHistory();

  const [amount, setAmount] = useState("");
  const [step, setStep] = useState("scan");   // "scan" | "confirm" | "success"
  const [message, setMessage] = useState("");
  const [loading, setLoading] = useState(false);

  /* ── Step 1: "Scan" the dummy QR → move to confirm step ──────────────── */
  const handleScan = () => {
    if (!amount || parseFloat(amount) <= 0) {
      setMessage("Please enter a valid amount before scanning.");
      return;
    }
    setMessage("");
    setStep("confirm");
  };

  /* ── Step 2: Confirm → call the existing deposit API ──────────────────
     NOTE: this reuses the same /banking deposit endpoint as the Deposit
     page, since this is a dummy QR flow simulating a deposit into the
     user's own account rather than a real merchant payment rail. ──────── */
  const handleConfirm = async () => {
    setLoading(true);
    try {
      await deposit({
        accountId: parseInt(getAccountId(), 10),
        amount: parseFloat(amount)
      });

      setStep("success");
      localStorage.setItem("refreshDashboard", "true");

    } catch (error) {
      console.error("QR payment error:", error);
      setMessage("Payment failed. Please try again.");
      setStep("scan");
    }
    setLoading(false);
  };

  const reset = () => {
    setAmount("");
    setMessage("");
    setStep("scan");
  };

  return (
    <div className="bg-light min-vh-100">
      <Navbar />

      <div className="d-flex">
        <Sidebar />

        <div className="container-fluid p-4">

          {message && (
            <div className="alert alert-danger d-flex align-items-center gap-2 mb-4 shadow-sm rounded-3" role="alert">
              <i className="bi bi-x-circle-fill fs-6"></i>
              <span>{message}</span>
            </div>
          )}

          <div className="row justify-content-center">
            <div className="col-12 col-md-7 col-lg-5">

              <div className="card border-0 shadow-sm rounded-4">
                <div className="card-header bg-white border-bottom fw-bold text-dark py-3 rounded-top-4">
                  <i className="bi bi-qr-code-scan me-2 text-primary"></i>
                  QR Payment
                  <span className="badge bg-secondary bg-opacity-10 text-secondary ms-2 fw-normal" style={{ fontSize: "11px" }}>
                    Demo Mode
                  </span>
                </div>

                <div className="card-body p-4 text-center">

                  {/* ── STEP 1: Scan ───────────────────────────────────── */}
                  {step === "scan" && (
                    <>
                      <p className="text-muted small mb-3">
                        Scan this QR code with any FinGenie-supported app to deposit funds instantly.
                      </p>

                      <div className="d-inline-block p-3 bg-white border rounded-4 shadow-sm mb-4">
                        <img src={DUMMY_QR_SVG} alt="Dummy QR Code" width="200" height="200" />
                      </div>

                      <div className="mb-4">
                        <label className="form-label fw-semibold small text-dark text-start d-block">
                          Amount to Deposit
                        </label>
                        <div className="input-group">
                          <span className="input-group-text bg-light">₹</span>
                          <input
                            type="number"
                            className="form-control"
                            placeholder="0.00"
                            min="0"
                            step="0.01"
                            value={amount}
                            onChange={(e) => setAmount(e.target.value)}
                          />
                        </div>
                      </div>

                      <button
                        className="btn btn-primary w-100 fw-semibold rounded-3 py-2"
                        onClick={handleScan}
                        disabled={!amount}
                      >
                        <i className="bi bi-qr-code-scan me-2"></i>
                        Simulate Scan &amp; Pay
                      </button>
                    </>
                  )}

                  {/* ── STEP 2: Confirm ────────────────────────────────── */}
                  {step === "confirm" && (
                    <>
                      <div className="bg-primary bg-opacity-10 rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{ width: "70px", height: "70px" }}>
                        <i className="bi bi-qr-code text-primary" style={{ fontSize: "32px" }}></i>
                      </div>

                      <h5 className="fw-bold text-dark mb-1">Confirm Payment</h5>
                      <p className="text-muted small mb-4">
                        Review the details below before confirming this deposit.
                      </p>

                      <div className="bg-light rounded-3 p-3 mb-4 text-start">
                        <div className="d-flex justify-content-between py-1">
                          <span className="text-muted small">Payment Method</span>
                          <span className="fw-semibold small">Dummy QR Code</span>
                        </div>
                        <div className="d-flex justify-content-between py-1">
                          <span className="text-muted small">Account</span>
                          <span className="fw-semibold small">#{getAccountId()}</span>
                        </div>
                        <hr className="my-2" />
                        <div className="d-flex justify-content-between py-1">
                          <span className="text-dark fw-semibold">Amount</span>
                          <span className="fw-bold text-primary fs-5">₹{parseFloat(amount).toLocaleString("en-IN")}</span>
                        </div>
                      </div>

                      <div className="d-flex gap-2">
                        <button
                          className="btn btn-outline-secondary flex-fill rounded-3 fw-semibold"
                          onClick={reset}
                          disabled={loading}
                        >
                          Cancel
                        </button>
                        <button
                          className="btn btn-success flex-fill rounded-3 fw-semibold"
                          onClick={handleConfirm}
                          disabled={loading}
                        >
                          {loading
                            ? <><span className="spinner-border spinner-border-sm me-2"></span>Processing...</>
                            : <><i className="bi bi-check-circle me-2"></i>Confirm Payment</>
                          }
                        </button>
                      </div>
                    </>
                  )}

                  {/* ── STEP 3: Success ────────────────────────────────── */}
                  {step === "success" && (
                    <>
                      <div className="bg-success bg-opacity-10 rounded-circle d-inline-flex align-items-center justify-content-center mb-3" style={{ width: "80px", height: "80px" }}>
                        <i className="bi bi-check-lg text-success" style={{ fontSize: "40px" }}></i>
                      </div>

                      <h5 className="fw-bold text-dark mb-1">Payment Successful</h5>
                      <p className="text-muted small mb-4">
                        ₹{parseFloat(amount).toLocaleString("en-IN")} has been deposited to your account.
                      </p>

                      <div className="d-flex gap-2">
                        <button
                          className="btn btn-outline-primary flex-fill rounded-3 fw-semibold"
                          onClick={reset}
                        >
                          <i className="bi bi-qr-code-scan me-2"></i>
                          New Payment
                        </button>
                        <button
                          className="btn btn-primary flex-fill rounded-3 fw-semibold"
                          onClick={() => history.push("/dashboard")}
                        >
                          <i className="bi bi-speedometer2 me-2"></i>
                          Go to Dashboard
                        </button>
                      </div>
                    </>
                  )}

                </div>
              </div>

              <p className="text-center text-muted small mt-3">
                <i className="bi bi-info-circle me-1"></i>
                This is a simulated QR payment for demo purposes. No real merchant network is involved.
              </p>

            </div>
          </div>

        </div>
      </div>
    </div>
  );
}

export default QrPayment;
